const s = wb.getWorksheet('Sheet1');
const mins = s.getRange('B20:F20').getValues()[0] as number[];
const maxs = s.getRange('B21:F21').getValues()[0] as number[];
const units = s.getRange('B2:F18').getValues() as number[][];
const res = s.getRange('I2:I18').getValues().map(r => r[0] as number);
const unresolved: any[] = [];
const out = units.map((row, i) => {
  const r = [...row];
  let left = res[i];
  if (left > 0) {
    for (let c = 0; c < 5 && left > 0; c++) {
      if (r[c] === 0) continue;
      const d = Math.min(left, Math.max(0, maxs[c] - r[c]));
      r[c] += d; left -= d;
    }
  } else if (left < 0) {
    for (let c = 4; c >= 0 && left < 0; c--) {
      if (r[c] === 0) continue;
      const d = Math.min(-left, Math.max(0, r[c] - mins[c]));
      r[c] -= d; left += d;
    }
  }
  if (left !== 0) unresolved.push([i + 2, left]);
  return r;
});
s.getRange('B2:F18').setValues(out);
s.getRange('I2:I18').setValues(res.map(() => [0]));
const check = out.map((r, i) => r.reduce((a, b) => a + b, 0) - units[i].reduce((a, b) => a + b, 0) - res[i]);
log('unresolved', JSON.stringify(unresolved), 'sumcheck nonzero', check.filter(x => x !== 0).length);
wb.getRange('A1:I21')

